SELECT u.*, o.org_name AS orgName
FROM agri_md_user u
LEFT JOIN agri_md_organization o ON u.org_id = o.id
WHERE u.del_flag = 0

    AND u.user_code LIKE CONCAT('%', #{dto.userCode}, '%')


    AND u.username LIKE CONCAT('%', #{dto.username}, '%')


    AND u.real_name LIKE CONCAT('%', #{dto.realName}, '%')


    AND u.phone LIKE CONCAT('%', #{dto.phone}, '%')


    AND u.email LIKE CONCAT('%', #{dto.email}, '%')


    AND u.user_type = #{dto.userType}


    AND u.real_name_status = #{dto.realNameStatus}


    AND u.user_status = #{dto.userStatus}


    AND u.org_id = #{dto.orgId}


    AND u.status = #{dto.status}

ORDER BY u.create_time DESC
LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*)
FROM agri_md_user u
WHERE u.del_flag = 0

    AND u.user_code LIKE CONCAT('%', #{dto.userCode}, '%')


    AND u.username LIKE CONCAT('%', #{dto.username}, '%')


    AND u.real_name LIKE CONCAT('%', #{dto.realName}, '%')


    AND u.phone LIKE CONCAT('%', #{dto.phone}, '%')


    AND u.email LIKE CONCAT('%', #{dto.email}, '%')


    AND u.user_type = #{dto.userType}


    AND u.real_name_status = #{dto.realNameStatus}


    AND u.user_status = #{dto.userStatus}


    AND u.org_id = #{dto.orgId}


    AND u.status = #{dto.status}
